const NAME = "Rasenschach XI";
const VERSION = "35.168";
const VERSION_INFO = "Zusammengeführt mit Codex — drei Befunde zurückgeholt.";

/* Fester Zufallsstrom aus einer Zeichenkette — damit Angebote des eigenen
   Vereins nicht bei jedem Klick anders aussehen.                        */
const hashStr = (t) => { let h = 2166136261; for (let i = 0; i < t.length; i++) { h ^= t.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
/* Fester Winkel je Gegenstand — sieht zufällig aus, ist es aber nicht.
   Dieselbe Errungenschaft, dieselbe Karte sitzt dadurch immer gleich schief. */
const winkel = (k) => (((hashStr(String(k)) % 13) - 6) / 8) + "deg";
const mulberry = (a) => () => { a |= 0; a = (a + 0x6D2B79F5) | 0;
  let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };

const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
/* ---------------------------------------- Zufall, austauschbar -----------
   V10 aus dem Bericht: „Zufallsquelle fuer Tests austauschbar machen. Ein
   Seed muss mit Version und Szenariokonfiguration nachvollziehbar sein."

   WARUM DAS NOETIG IST. Jede Messung an diesem Spiel streut, weil jeder Lauf
   neu wuerfelt. Sechs Pruefungen mussten in dieser Reihe auf groessere
   Stichproben umgestellt werden, und das Zielband „Laufbahnen bis
   Vollausbau" hat viermal grundlos rot gemeldet. Ohne feste Startwerte
   laesst sich nicht sagen, ob eine Aenderung gewirkt hat oder der Wuerfel
   anders fiel.

   IM SPIEL AENDERT SICH NICHTS. `zufall` ist standardmaessig `Math.random`;
   nur der Pruefstand setzt sie um. Ein festes Spiel waere kein Spiel — und
   ein Seed, der versehentlich in die Auslieferung geraet, waere ein Fehler,
   den niemand bemerkt. Deshalb kein Feld im Spielstand, keine Einstellung,
   nur eine Ausfuhr fuer Werkzeuge.

   Der Generator ist ein mulberry32: klein, schnell, gut genug fuer
   Verteilungen. Kryptografisch taugt er nichts — das braucht hier niemand. */
let zufall = Math.random;
const zufallSetzen = (seed) => {
  if (seed == null) { zufall = Math.random; return null; }
  let z = (seed >>> 0) || 1;
  zufall = () => {
    z = (z + 0x6D2B79F5) >>> 0;
    let t = z;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  return seed;
};

const rnd = (a, b) => a + zufall() * (b - a);
const ri = (a, b) => Math.floor(rnd(a, b + 1));
const pick = (a) => a[Math.floor(zufall() * a.length)];
const chance = (p) => zufall() < p;
const gauss = (m, s) => { let u = 0, v = 0; while (!u) u = zufall(); while (!v) v = zufall(); return m + s * Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v); };
const eur = (m) => {
  if (m == null || !isFinite(m)) return "—";
  const x = Math.abs(m), s = m < 0 ? "−" : "";
  if (x >= 1000) return s + (x / 1000).toFixed(2) + " Mrd";
  if (x >= 100) return s + Math.round(x) + " Mio";
  if (x >= 10) return s + x.toFixed(0) + " Mio";
  if (x >= 1) return s + x.toFixed(1) + " Mio";
  return s + Math.round(x * 1000) + " Tsd";
};
const hash = (s) => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return Math.abs(h); };
/* Poisson-verteilte Torzahl für die Spielsimulation */
const poisson = (l) => { const L = Math.exp(-Math.max(.02, l)); let k = 0, p = 1, g = 0;
  do { k++; p *= zufall(); } while (p > L && g++ < 60); return k - 1; };
/* Zwei Farben mischen. Für den Lippenstift: der Grundton bleibt erkennbar,
   der Farbstich legt sich darüber. Eine feste Farbe säße auf hellen und
   dunklen Hauttönen nie zugleich richtig. */
const mischFarbe = (a, b, anteil) => {
  try {
    const A = parseInt(String(a).slice(1), 16), B = parseInt(String(b).slice(1), 16);
    const m = (v, w) => Math.round(v + (w - v) * anteil);
    const h = (v) => v.toString(16).padStart(2, "0");
    return "#" + h(m(A >> 16 & 255, B >> 16 & 255)) + h(m(A >> 8 & 255, B >> 8 & 255))
      + h(m(A & 255, B & 255));
  } catch (e) { return a; }
};

/* ---- Kontrastgrund fuer das Portraet (35.63) ---------------------------
   Ein Portraet ist nur zu erkennen, wenn der Kopf sich vom Grund abhebt. Bei
   schwarzem Haar auf sehr dunklem Grund tut er das nicht — von Kevin auf dem
   Geraet gemeldet, gemessen mit Kontrast 1,02 (1,0 heisst: kein Unterschied).

   HAAR_DUNKELSTE ist der dunkelste Ton, den die Haarpalette hergibt. Gegen
   IHN wird gemessen, nicht gegen ein gedachtes Schwarz — sonst waere die
   Grenze willkuerlich. GRUND_MIN ist bewusst 2,5 und nicht die 4,5 der
   Textlesbarkeit: hier geht es um eine Silhouette, nicht um Buchstaben, und
   ein zu heller Grund macht aus dem Portraet ein Passfoto. */
/* AUS DER PALETTE, nicht abgeschrieben. Im ersten Entwurf stand hier fest
   "#141414" — geraten. Der dunkelste Ton in HAIRC ist "#17120F", also etwas
   anderes. Eine Grenze, die gegen einen erfundenen Wert misst, misst nichts:
   aendert jemand die Palette, bleibt die Grenze stehen und die Silhouette
   verschwindet wieder, ohne dass etwas meldet.
   Als Funktion, weil HAIRC weiter unten steht — beim Aufruf zur Zeichenzeit
   ist die Palette da, bei einer Konstante hier oben waere sie es nicht. */
const haarDunkelste = () => (HAIRC || ["#17120F"]).reduce((a, b) =>
  (helligkeit(a) <= helligkeit(b) ? a : b));
const GRUND_MIN = 2.5;
const helligkeit = (hex) => {
  const n = parseInt(String(hex).slice(1), 16);
  const f = (v) => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
  return 0.2126 * f((n >> 16) & 255) + 0.7152 * f((n >> 8) & 255) + 0.0722 * f(n & 255);
};
const kontrast = (a, b) => {
  const h = helligkeit(a), d = helligkeit(b);
  return (Math.max(h, d) + 0.05) / (Math.min(h, d) + 0.05);
};
/* Schrittweise aufhellen, bis die Grenze erreicht ist. Der Deckel bei 40
   Schritten ist eine Bremse, keine Erwartung: er greift nur, wenn jemand die
   Palette so aendert, dass die Grenze unerreichbar wird — dann wird der Grund
   hell, statt dass die Schleife stehenbleibt. */
const grundAufhellen = (hex) => {
  let c = hex;
  const dunkel = haarDunkelste();
  for (let i = 0; i < 40 && kontrast(c, dunkel) < GRUND_MIN; i++) c = shade(c, 6);
  return c;
};

const shade = (hex, amt) => {
  const n = parseInt(hex.slice(1), 16);
  const f = (v) => clamp(Math.round(v + amt), 0, 255);
  return "#" + [f((n >> 16) & 255), f((n >> 8) & 255), f(n & 255)].map((v) => v.toString(16).padStart(2, "0")).join("");
};

