/* Summiert die dauerhaften Wirkungen aller Anschaffungen */
function perk(p, k) {
  let v = 0;
  const a = p && p.assets ? p.assets : [];
  for (const id of a) { const it = shopItem(id); if (it && it.perk && it.perk[k]) v += it.perk[k]; }
  return v;
}
