    ls: p.seasons[p.seasons.length - 1] || null,
    conf: confOf(p.club.c), natconf: NAT_CONF[p.nation.id], nat: p.nation,
    pn: p.life.partner || partnerName(p.nation.id),
    prev: p.prevClub || "deinem alten Verein",
